importScripts('./vendor/lame.min.js');
self.onmessage=({data:{channels,sampleRate}})=>{try{const encoder=new lamejs.Mp3Encoder(channels.length,sampleRate,128),chunks=[],pcm=channels.map(c=>Int16Array.from(c,v=>{v=Math.max(-1,Math.min(1,v));return v<0?v*32768:v*32767;}));for(let i=0;i<pcm[0].length;i+=1152){const part=encoder.encodeBuffer(pcm[0].subarray(i,i+1152),pcm[1]?.subarray(i,i+1152));if(part.length)chunks.push(new Uint8Array(part));}const end=encoder.flush();if(end.length)chunks.push(new Uint8Array(end));self.postMessage({blob:new Blob(chunks,{type:'audio/mpeg'})});}catch(e){self.postMessage({error:e.message});}};
